import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"URI Protocol (lertaro://)","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/uri-protocol.md","filePath":"user-guide/uri-protocol.md","lastUpdated":1787586465000}'),i={name:"user-guide/uri-protocol.md"};function o(r,e,l,d,c,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="uri-protocol-lertaro" tabindex="-1">URI Protocol (lertaro://) <a class="header-anchor" href="#uri-protocol-lertaro" aria-label="Permalink to &quot;URI Protocol (lertaro://)&quot;">​</a></h1><p>On its first run, Lertaro automatically registers the <strong><code>lertaro://</code></strong> custom protocol with Windows. Web hyperlinks, desktop shortcuts, automation scripts, and third-party tools can use this protocol to invoke specific searches, navigate directly to settings sections, or initiate wireless transfers.</p><h2 id="_1-scheme-architecture-single-instance-routing" tabindex="-1">1. Scheme Architecture &amp; Single-Instance Routing <a class="header-anchor" href="#_1-scheme-architecture-single-instance-routing" aria-label="Permalink to &quot;1. Scheme Architecture &amp; Single-Instance Routing&quot;">​</a></h2><ul><li><strong>Out of the Box</strong>: No manual registry editing is required. Lertaro configures and validates registration upon launch.</li><li><strong>Single-Instance Forwarding</strong>: If Lertaro is already running in the background, opening a <code>lertaro://</code> link forwards the request directly to the active foreground instance without spawning duplicate processes. If Lertaro is not running, Windows starts the application and executes the requested route immediately.</li></ul><h2 id="_2-complete-uri-route-cheat-sheet" tabindex="-1">2. Complete URI Route Cheat Sheet <a class="header-anchor" href="#_2-complete-uri-route-cheat-sheet" aria-label="Permalink to &quot;2. Complete URI Route Cheat Sheet&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">URI Route</th><th style="text-align:left;">Description &amp; Visual Outcome</th></tr></thead><tbody><tr><td style="text-align:left;"><code>lertaro://</code></td><td style="text-align:left;">Activates and displays the Quick Window (equivalent to double-tapping <code>Ctrl</code>).</td></tr><tr><td style="text-align:left;"><code>lertaro://search/[keyword]</code></td><td style="text-align:left;">Activates the Quick Window, pre-populates <code>[keyword]</code>, and filters immediately.</td></tr><tr><td style="text-align:left;"><code>lertaro://fullsearch/[keyword]</code></td><td style="text-align:left;">Opens the Full Window with <code>[keyword]</code> pre-populated.</td></tr><tr><td style="text-align:left;"><code>lertaro://settings/page/[section]</code></td><td style="text-align:left;">Opens the Settings window and switches directly to the specified top-level section.</td></tr><tr><td style="text-align:left;"><code>lertaro://settings/entry/[id]</code></td><td style="text-align:left;">Opens Settings and navigates straight to a specific setting item, highlighting it.</td></tr><tr><td style="text-align:left;"><code>lertaro://localsend</code></td><td style="text-align:left;">Opens a blank LocalSend wireless transfer window.</td></tr><tr><td style="text-align:left;"><code>lertaro://localsend/items/[encoded_path...]</code></td><td style="text-align:left;">Opens LocalSend in file mode with one or more pre-populated file/folder paths.</td></tr><tr><td style="text-align:left;"><code>lertaro://localsend/text/[encoded_text]</code></td><td style="text-align:left;">Opens LocalSend in text mode with pre-populated text ready to send.</td></tr></tbody></table><h3 id="settings-section-keywords-section" tabindex="-1">Settings Section Keywords <code>[section]</code> <a class="header-anchor" href="#settings-section-keywords-section" aria-label="Permalink to &quot;Settings Section Keywords \`[section]\`&quot;">​</a></h3><p>Section names are case-insensitive and match the sidebar navigation in the Settings window:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Service      - Service Status</span></span>
<span class="line"><span>Index        - Indexing Settings</span></span>
<span class="line"><span>General      - General Settings</span></span>
<span class="line"><span>Appearance   - Appearance &amp; Themes</span></span>
<span class="line"><span>Hotkeys      - Hotkeys &amp; Shortcuts</span></span>
<span class="line"><span>Plugins      - Plugin Management</span></span>
<span class="line"><span>Favorites    - Favorites</span></span>
<span class="line"><span>History      - Search History</span></span>
<span class="line"><span>QuickPanel   - Quick Panel</span></span>
<span class="line"><span>About        - About &amp; Updates</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>The numeric ID in <code>lertaro://settings/entry/[id]</code> is dynamically generated by the internal <a href="./instant-answers.html#2-keyword-triggered-plugin-extensions"><strong>Settings Search</strong></a> plugin. Because IDs may shift across versions, use <code>lertaro://settings/page/[section]</code> for external scripts and documentation links.</p></div><h2 id="_3-localsend-parameters-encoding-standards" tabindex="-1">3. LocalSend Parameters &amp; Encoding Standards <a class="header-anchor" href="#_3-localsend-parameters-encoding-standards" aria-label="Permalink to &quot;3. LocalSend Parameters &amp; Encoding Standards&quot;">​</a></h2><p>When triggering LocalSend via URI, every path or text snippet must be properly URL-encoded (e.g. <code>:</code> as <code>%3A</code>, <code>\\</code> as <code>%5C</code>, and spaces as <code>%20</code>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Pre-filling multiple file paths</span></span>
<span class="line"><span>lertaro://localsend/items/C%3A%5CUsers%5Ctestuser%5CDesktop%5Cdoc.pdf/D%3A%5CShared%5Cphotos</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Pre-filling text payload</span></span>
<span class="line"><span>lertaro://localsend/text/Hello%20from%20Lertaro%21</span></span></code></pre></div><ul><li><strong>Security Constraint</strong>: All file paths must be existing absolute paths on the local machine. Links containing payload data open the device selection screen; they never initiate transfers automatically.</li></ul><h2 id="_4-integration-examples" tabindex="-1">4. Integration Examples <a class="header-anchor" href="#_4-integration-examples" aria-label="Permalink to &quot;4. Integration Examples&quot;">​</a></h2><h3 id="markdown-knowledge-bases" tabindex="-1">Markdown &amp; Knowledge Bases <a class="header-anchor" href="#markdown-knowledge-bases" aria-label="Permalink to &quot;Markdown &amp; Knowledge Bases&quot;">​</a></h3><p>Embed direct links inside Obsidian, Notion, or internal Markdown documents:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Open [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Lertaro Appearance Settings</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">lertaro://settings/page/Appearance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Search for [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Project Financials</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">lertaro://search/financial%20report%202026</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="desktop-shortcuts-scripts" tabindex="-1">Desktop Shortcuts &amp; Scripts <a class="header-anchor" href="#desktop-shortcuts-scripts" aria-label="Permalink to &quot;Desktop Shortcuts &amp; Scripts&quot;">​</a></h3><p>Create a standard Windows shortcut and set the target to:</p><div class="language-cmd vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lertaro://fullsearch/D:\\Projects\\</span></span></code></pre></div><p>Invoke from PowerShell:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Start-Process</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;lertaro://settings/page/General&quot;</span></span></code></pre></div><h2 id="_5-security-fault-tolerance" tabindex="-1">5. Security &amp; Fault Tolerance <a class="header-anchor" href="#_5-security-fault-tolerance" aria-label="Permalink to &quot;5. Security &amp; Fault Tolerance&quot;">​</a></h2><ul><li><strong>Silent Safety Handling</strong>: Because any webpage or external application can invoke URI schemes, Lertaro enforces strict validation on all incoming commands. Malformed or unrecognized routes are safely ignored and logged without triggering errors or unexpected behaviors.</li></ul>`,25)])])}const u=t(i,[["render",o]]);export{g as __pageData,u as default};
